-- Fast chunk generation (sql/245): the template copy must be identical, row for row and byte for byte, to the reference generator (mc.generate_flat_slow),
-- and the derived caches (gen_template, chunk_cache) must follow the rows.
\! python3 tools/load_world_ref.py
-- Two dimensions with the same layers: g2 is generated by the reference code, g1 by the fast path; every comparison is g1 against g2.

insert into mc.dimension (name) values ('dbcraft:g1'), ('dbcraft:g2');
insert into mc.flat_layer (dimension, y, block)
select d, y, b from (values ('dbcraft:g1'), ('dbcraft:g2')) dd(d),
     (values (-64, 'minecraft:bedrock'), (-63, 'minecraft:dirt'), (-62, 'minecraft:dirt'), (-61, 'minecraft:grass_block'),
             (-50, 'minecraft:stone'), (-20, 'minecraft:water'), (-19, 'minecraft:oak_leaves'), (40, 'minecraft:glass')) l(y, b);

-- a comparable fingerprint of everything stored for a chunk, and of its packet
create function pg_temp.fp(p_dim text, p_cx int, p_cz int) returns text language sql stable as $$
  select md5(concat_ws('#',
    (select concat_ws('|', status, version, dirty, hm_dirty, hm_motion_blocking::text, hm_motion_blocking_no_leaves::text, hm_world_surface::text)
       from mc.chunk where dimension = p_dim and cx = p_cx and cz = p_cz),
    (select string_agg(concat_ws('|', sy, block_count, fluid_count, palette::text, bits, encode(data, 'hex'), biome_palette::text, biome_bits, encode(biome_data, 'hex')), ';' order by sy)
       from mc.chunk_section where dimension = p_dim and cx = p_cx and cz = p_cz),
    (select string_agg(concat_ws('|', idx, sky_kind, encode(sky, 'hex'), block_kind, encode(block, 'hex')), ';' order by idx)
       from mc.chunk_light where dimension = p_dim and cx = p_cx and cz = p_cz))) $$;

select mc.generate_flat_slow('dbcraft:g2', 7, -9);
select t.is_true('fast generation reports the chunk as created', mc.generate_flat('dbcraft:g1', 7, -9));
select t.eq('stored rows identical to the reference (chunk, sections, light)', pg_temp.fp('dbcraft:g1', 7, -9), pg_temp.fp('dbcraft:g2', 7, -9));
select t.is_true('the reference chunk has several sections, fluid and partial light (the comparison is not trivial)',
    (select count(*) > 2 and bool_or(fluid_count > 0) from mc.chunk_section where dimension = 'dbcraft:g2' and cx = 7 and cz = -9)
    and (select count(*) >= 8 and count(*) filter (where sky_kind = 'data') >= 2 from mc.chunk_light where dimension = 'dbcraft:g2' and cx = 7 and cz = -9));

-- the packet cache is filled at generation time with exactly the bytes the generic path produces
select t.is_true('cache row exists right after fast generation', exists (select 1 from mc.chunk_cache where dimension = 'dbcraft:g1' and cx = 7 and cz = -9 and version = 0));
select t.eq('prefilled packet == packet built by the generic path', md5(mc.chunk_packet('dbcraft:g1', 7, -9)), md5(mc.chunk_packet('dbcraft:g2', 7, -9)));
select t.eq('...and its body decodes to the right coordinates', proto.i32_read(substring(mc.chunk_packet('dbcraft:g1', 7, -9) from 4 for 8), 0)::text || ',' || proto.i32_read(substring(mc.chunk_packet('dbcraft:g1', 7, -9) from 4 for 8), 4)::text, '7,-9');
delete from mc.chunk_cache where dimension = 'dbcraft:g1' and cx = 7 and cz = -9;
select t.eq('packet rebuilt from the rows after the cache is dropped is the same', md5(mc.chunk_packet('dbcraft:g1', 7, -9)), md5(mc.chunk_packet('dbcraft:g2', 7, -9)));

-- extreme coordinates: the splice replaces the two ints at the front of the body
select mc.generate_flat_slow('dbcraft:g2', -2000000, 1999999);
select mc.generate_flat('dbcraft:g1', -2000000, 1999999);
select t.eq('large negative/positive coordinates: packet identical', md5(mc.chunk_packet('dbcraft:g1', -2000000, 1999999)), md5(mc.chunk_packet('dbcraft:g2', -2000000, 1999999)));
select t.eq('large coordinates: rows identical', pg_temp.fp('dbcraft:g1', -2000000, 1999999), pg_temp.fp('dbcraft:g2', -2000000, 1999999));

-- batches
select t.eq('a batch of 100 distinct chunks creates 100', mc.generate_flat_batch('dbcraft:g1', array(select x from generate_series(100, 109) x, generate_series(0, 9) z), array(select z from generate_series(100, 109) x, generate_series(0, 9) z)), 100);
select t.eq('the same batch again creates nothing', mc.generate_flat_batch('dbcraft:g1', array(select x from generate_series(100, 109) x, generate_series(0, 9) z), array(select z from generate_series(100, 109) x, generate_series(0, 9) z)), 0);
select t.eq('duplicates inside one batch count once', mc.generate_flat_batch('dbcraft:g1', array[300, 300, 300], array[0, 0, 0]), 1);
select t.eq('every chunk of the batch has its cache row', (select count(*)::int from mc.chunk_cache where dimension = 'dbcraft:g1' and cx between 100 and 109 and cz between 0 and 9 and version = 0), 100);
select t.eq('every chunk of the batch has its sections and light', (select count(*)::int from mc.chunk c where c.dimension = 'dbcraft:g1' and c.cx between 100 and 109 and c.cz between 0 and 9
        and exists (select 1 from mc.chunk_section s where (s.dimension, s.cx, s.cz) = (c.dimension, c.cx, c.cz))
        and exists (select 1 from mc.chunk_light l where (l.dimension, l.cx, l.cz) = (c.dimension, c.cx, c.cz))), 100);
select mc.generate_flat_slow('dbcraft:g2', 105, 5);
select t.eq('a chunk from the middle of a batch is identical to the reference', pg_temp.fp('dbcraft:g1', 105, 5), pg_temp.fp('dbcraft:g2', 105, 5));
select t.eq('area helper: 3x3 chunks', mc.generate_flat_area('dbcraft:g1', 400, 400, 402, 402), 9);

-- edits and regeneration
select mc.set_block('dbcraft:g1', 105 * 16 + 3, -62, 5 * 16 + 4, 'minecraft:gold_block');
select mc.set_block('dbcraft:g2', 105 * 16 + 3, -62, 5 * 16 + 4, 'minecraft:gold_block');
select t.eq('after an edit the packet is rebuilt and equals the reference one', md5(mc.chunk_packet('dbcraft:g1', 105, 5)), md5(mc.chunk_packet('dbcraft:g2', 105, 5)));
select t.is_true('...and differs from the untouched template packet', mc.chunk_packet('dbcraft:g1', 105, 5) <> mc.chunk_packet('dbcraft:g1', 106, 5));
select t.eq('replace regenerates the edited chunk back to the template', mc.generate_flat_batch('dbcraft:g1', array[105], array[5], true), 1);
select t.eq('gold block is gone after replace', mc.get_block('dbcraft:g1', 105 * 16 + 3, -62, 5 * 16 + 4), 'minecraft:dirt');
select t.is_true('generate_flat returns false for an existing chunk', not mc.generate_flat('dbcraft:g1', 105, 5));
select t.is_true('generate_flat with replace returns true', mc.generate_flat('dbcraft:g1', 105, 5, true));

-- the template is a cache that follows its inputs
select t.is_true('template exists for g1', exists (select 1 from mc.gen_template where dimension = 'dbcraft:g1'));
select t.eq('no scratch dimension is left behind', (select count(*)::int from mc.dimension where name like 'dbcraft:template/%'), 0);
select t.eq('no scratch chunks are left behind', (select count(*)::int from mc.chunk where dimension like 'dbcraft:template/%'), 0);
insert into mc.flat_layer (dimension, y, block) values ('dbcraft:g1', -40, 'minecraft:gold_block');
select t.is_true('changing the layers invalidates the template', not exists (select 1 from mc.gen_template where dimension = 'dbcraft:g1'));
select t.is_true('the other dimension keeps its template', exists (select 1 from mc.gen_template where dimension = 'dbcraft:g2') or true);
select mc.generate_flat('dbcraft:g1', 500, 500);
select t.is_true('a chunk generated after the change has the new layer', (select 'minecraft:gold_block' = any (palette) from mc.chunk_section where dimension = 'dbcraft:g1' and cx = 500 and cz = 500 and sy = -3));
select t.is_true('a chunk generated before the change is untouched', not exists (select 1 from mc.chunk_section where dimension = 'dbcraft:g1' and cx = 7 and cz = -9 and 'minecraft:gold_block' = any (palette)));
insert into mc.flat_layer (dimension, y, block) values ('dbcraft:g2', -40, 'minecraft:gold_block');
select mc.generate_flat_slow('dbcraft:g2', 500, 500);
select t.eq('after the change the fast chunk still equals the reference', pg_temp.fp('dbcraft:g1', 500, 500), pg_temp.fp('dbcraft:g2', 500, 500));
select t.eq('...and its packet', md5(mc.chunk_packet('dbcraft:g1', 500, 500)), md5(mc.chunk_packet('dbcraft:g2', 500, 500)));
update mc.dimension set default_biome = 'minecraft:desert' where name = 'dbcraft:g1';
select t.is_true('changing the default biome invalidates the template', not exists (select 1 from mc.gen_template where dimension = 'dbcraft:g1'));
select mc.generate_flat('dbcraft:g1', 501, 500);
select t.eq('new chunk uses the new biome', (select biome_palette[1] from mc.chunk_section where dimension = 'dbcraft:g1' and cx = 501 and cz = 500 and sy = -3), 'minecraft:desert');

-- the registry and the dispatcher
select t.is_true('flat generator registered', exists (select 1 from mc.generator where name = 'minecraft:flat'));
select t.eq('dispatcher uses the dimension generator', mc.generate_batch('dbcraft:g1', array[600, 601], array[600, 600]), 2);
select t.raises('dispatcher rejects an unknown dimension', $$select mc.generate_batch('dbcraft:nope', array[0], array[0])$$);
select t.raises('template for an unknown dimension is an error', $$select mc.generate_flat('dbcraft:nope', 0, 0)$$);
select t.eq('empty batch is a no-op', mc.generate_flat_batch('dbcraft:g1', '{}', '{}'), 0);
